/* Round 3: shared metallic accent tokens, accessible accessory controls. */
a{color:var(--gold-text);text-decoration-color:var(--gold-dark)}
.button-pill{border-color:var(--gold)}
@media(hover:hover){.button-pill:hover:not(:disabled){border-color:var(--gold-light)}}
.accessory-list{display:grid;gap:12px;margin-top:20px}
.accessory{display:flex;align-items:flex-start;gap:14px;min-height:64px;padding:16px;border:1px solid var(--gold-dark);border-radius:12px;cursor:pointer;color:var(--ink);font-size:22px;line-height:1.4}
.accessory input{appearance:none;-webkit-appearance:none;flex:0 0 28px;width:28px;height:28px;margin:2px 0 0;border:2px solid var(--gold-dark);border-radius:4px;background:var(--paper);display:grid;place-content:center}
.accessory input:checked{background:var(--gold)}
.accessory input:checked:before{content:'';width:8px;height:14px;border:solid var(--ink);border-width:0 3px 3px 0;transform:rotate(45deg) translate(-1px,-1px)}
.accessory:has(input:checked){border-color:var(--gold-dark);box-shadow:inset 0 0 0 1px var(--gold-dark)}
.accessory small{display:block;margin-top:4px;font-size:var(--text-label);color:var(--label)}
.options legend{font-weight:400;color:var(--ink)}
.order-prices{margin:0 0 20px;max-width:650px}
.order-prices>div{display:flex;justify-content:space-between;gap:20px;padding:14px 0;border-top:1px solid var(--line)}
.order-prices dt{color:var(--ink);font-weight:400}.order-prices dd{margin:0;text-align:right;overflow-wrap:anywhere}
.confirmation-accessories{margin-bottom:24px}#confirmation-accessories{white-space:pre-line;margin-top:16px;line-height:1.4}
.nojs-options{padding-block:24px;font-size:var(--text-body);line-height:1.4}.nojs-options ul{padding-left:26px;margin-top:16px}.nojs-options li+li{margin-top:12px}
@media(forced-colors:active){.accessory input{appearance:auto;-webkit-appearance:auto}.accessory input:checked:before{content:none}}
